# Generated by build.py from recipe.yml for recipe http-fail-a-proxy-tunnel. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/hello.txt'), "hello from surl`n")
cmd /c 'openssl req -x509 -newkey rsa:2048 -nodes -keyout server.key -out server.pem -days 30 -subj "/CN=127.0.0.1" -addext "subjectAltName=IP:127.0.0.1"'
$server0 = Start-Process surl -ArgumentList '--directory', 'site', 'http://127.0.0.1:8080/', 'https://127.0.0.1:8081/', '--cert', 'server.pem', '--key', 'server.key', '--fault', '"error;scheme=http;reply=503;path=/busy.txt"', '-v', '--log-file', 'origin.log' -PassThru -NoNewWindow
$server1 = Start-Process surl -ArgumentList '--proxy', 'http://127.0.0.1:8082/', '--fault', '"error;scheme=http-proxy;command=CONNECT;reply=503"', '-v', '--log-file', 'proxy.log' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -sS --cacert server.pem -x http://127.0.0.1:8082/ https://127.0.0.1:8081/hello.txt } finally { Stop-Process $server0; Stop-Process $server1 }
